#include "libCLAYPacketEngine.h"
#include <stdio.h>

#define CHECK(test) do { if (!(test)) { fprintf(stderr, "packet ABI check failed at line %d\n", __LINE__); return 1; } } while (0)

// Input is generated by CLAYCoreChecks --packet-fixture. Contains examples only.
int main(void) {
    static uint8_t profile[2 * 1024 * 1024 + 1];
    uint8_t packet[1500] = {0x60};
    const size_t length = fread(profile, 1, sizeof(profile), stdin);
    CHECK(!ferror(stdin) && length > 0 && length < sizeof(profile));
    CHECK(clay_engine_start(profile, (int32_t)length, 0, 0) == 0);
    CHECK(clay_engine_start(profile, (int32_t)length, 1, 3) == 0);
    uint64_t previous = 0;
    for (int32_t mode = 0; mode < 3; ++mode) {
        const uint64_t id = clay_engine_start(profile, (int32_t)length, 5, mode);
        CHECK(id > previous);
        CHECK(clay_engine_start(profile, (int32_t)length, 1, 0) == 0);
        clay_engine_stop(previous);
        CHECK(clay_engine_read(previous, packet, sizeof(packet), 10) < 0);
        CHECK(clay_engine_offer(id, packet, sizeof(packet)) < 0);
        CHECK(clay_engine_read(id, packet, sizeof(packet) - 1, 10) < 0);
        CHECK(clay_engine_read(id, packet, sizeof(packet), 10) == 0);
        clay_engine_stop(id);
        CHECK(clay_engine_read(id, packet, sizeof(packet), 10) < 0);
        previous = id;
    }
    uint8_t lab[] = "{\"proxies\":[{\"name\":\"node-11111111-1111-4111-8111-111111111111\","
        "\"type\":\"vless\",\"server\":\"127.0.0.1\",\"port\":18080,"
        "\"uuid\":\"56dc6c3e-8793-4d37-a363-f9f19db29c6d\"}],\"rules\":[\"MATCH,CLAY\"]}";
    const int32_t labSize = (int32_t)(sizeof(lab) - 1);
    CHECK(clay_engine_start_lab(lab, labSize, 2) == 0);
    const uint64_t id = clay_engine_start_lab(lab, labSize, 0);
    CHECK(id > previous);
    CHECK(clay_engine_replace_lab(previous, lab, labSize, 1) < 0);
    CHECK(clay_engine_replace_lab(id, lab, labSize, 2) < 0);
    CHECK(clay_engine_replace_lab(id, lab, labSize, 1) == 0);
    CHECK(clay_engine_read(id, packet, sizeof(packet), 10) == 0);
    clay_engine_stop(id);
    CHECK(clay_engine_replace_lab(id, lab, labSize, 0) < 0);
    puts("CLAY packet engine C ABI check passed");
    return 0;
}
